Here's the equivalent C++ code for the provided Python function. This function filters bounding boxes based on their area, using `std::vector` and standard C++ libraries. It assumes that `boxes_xyxy` is a 2D vector of integers or floats, and that `self._area_range` is a `std::pair` or `std::array` containing the minimum and maximum area thresholds.

```cpp
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>
#include <iostream>

// Assuming this is part of a class
class YourClass {
public:
    std::pair<float, float> _area_range;

    std::vector<int> _select_boxes_by_area(const std::vector<std::vector<float>>& boxes_xyxy) {
        if (_area_range.first == 0.0f && _area_range.second == 0.0f) {
            throw std::invalid_argument("Area range must be specified to filter boxes by area");
        }

        std::vector<float> areas;
        for (const auto& box : boxes_xyxy) {
            float width = box[2] - box[0];
            float height = box[3] - box[1];
            float area = width * height;
            areas.push_back(area);
        }

        std::vector<int> selected_indices;
        for (size_t i = 0; i < areas.size(); ++i) {
            if (areas[i] >= _area_range.first && areas[i] <= _area_range.second) {
                selected_indices.push_back(static_cast<int>(i));
            }
        }

        return selected_indices;
    }
};
```

### Notes:
- The function assumes that `boxes_xyxy` is a 2D vector of floats (or integers), where each inner vector represents a box with coordinates `[x1, y1, x2, y2]`.
- The `_area_range` is a `std::pair<float, float>` that defines the inclusive range of areas to filter.
- The function returns a vector of indices of the selected boxes.
- This is a direct translation of the logic from the Python function, using standard C++ types and containers.

